const LP_T=(x,y,t,o={})=>`<text x="${x}" y="${y}" ${LP_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}"${o.op?` fill-opacity="${o.op}"`:''}>${t}</text>`;
const LP_L=(x1,y1,x2,y2,col=LP_G,w=2,ex='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const LP_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}"${o.dash?` stroke-dasharray="${o.dash}"`:''}/>`;
const LP_ar=(x1,y1,x2,y2,col='#18213A',w=4,dash='')=>{const a=Math.atan2(y2-y1,x2-x1),h=16;return LP_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w,dash?`stroke-dasharray="${dash}"`:'')+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const LP_sub=(a,b)=>`${a}<tspan\tbaseline-shift="-0.2em"\tfont-size="72%">${b}</tspan>`;
const LP_badge=(x,y,n,col,op=1,r=17)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${col||INK}" fill-opacity="${op}"/>`+LP_T(x,y+8,n,{fs:22,fw:800,a:'middle',fill:'#FFFFFF'});
const LP_poly=(pts,col,w=3,fill='none',ex='')=>`<polyline points="${pts.map(p=>p[0].toFixed(1)+','+p[1].toFixed(1)).join(' ')}" fill="${fill}" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round" ${ex}/>`;
/* current along a horizontal dipole from x0 to x1 at y: a cosine half-arch of height h above the wire (computed points) */
const LP_cosI=(x0,x1,y,h,col,w=3,ex='')=>{const p=[];for(let i=0;i<=60;i++){const t=i/60;p.push([x0+(x1-x0)*t,y-h*Math.sin(Math.PI*t)])}return LP_poly(p,col,w,'none',ex)};
/* a horizontal centre-fed wire with the feed gap */
const LP_dip=(x0,x1,y,col=INK,w=6)=>{const m=(x0+x1)/2;return LP_L(x0,y,m-8,y,col,w)+LP_L(m+8,y,x1,y,col,w)+`<circle cx="${m}" cy="${y}" r="6" fill="${GRN}"/>`};
/* polar pattern of the half-wave dipole (axis vertical through cx,cy), two lobes, radius R: computed from cos(π/2 cosθ)/sinθ */
const LP_hwPat=(cx,cy,R,col,fill,o={})=>{const f=o.short?(t=>Math.sin(t)):(t=>Math.abs(Math.sin(t))<1e-6?0:Math.cos(Math.PI/2*Math.cos(t))/Math.sin(t));
 const lobe=s=>{const p=[];for(let i=0;i<=90;i++){const t=Math.PI*i/90,r=R*Math.abs(f(t));p.push([cx+s*r*Math.sin(t),cy-r*Math.cos(t)])}return p};
 const top=o.top;const cut=pts=>top?pts.filter(p=>p[1]<=cy+0.01):pts;
 return LP_poly(cut(lobe(1)),col,3,fill,o.dash?`stroke-dasharray="${o.dash}"`:'')+LP_poly(cut(lobe(-1)),col,3,fill,o.dash?`stroke-dasharray="${o.dash}"`:'')};
/* folded dipole: two parallel wires gap g apart, joined at the ends, fed at the centre of the lower one */
const LP_fold=(x0,x1,y,g,col=INK)=>{const m=(x0+x1)/2;return `<path d="M${m-8} ${y+g} H${x0+12} Q${x0} ${y+g} ${x0} ${y+g/2} Q${x0} ${y} ${x0+12} ${y} H${x1-12} Q${x1} ${y} ${x1} ${y+g/2} Q${x1} ${y+g} ${x1-12} ${y+g} H${m+8}" fill="none" stroke="${col}" stroke-width="6" stroke-linecap="round"/>`+`<circle cx="${m}" cy="${y+g}" r="6" fill="${GRN}"/>`};
/* small loop seen edge-on (ellipse) with its axis and the current arrow */
const LP_loopEdge=(cx,cy,rx,col=BLU)=>`<ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${rx*.3}" fill="none" stroke="${col}" stroke-width="5"/>`+LP_ar(cx-rx*.35,cy+rx*.3,cx+rx*.35,cy+rx*.3,col,3);

const LP_X=(x,y,s=14,col=RED)=>LP_L(x-s,y-s,x+s,y+s,col,6)+LP_L(x-s,y+s,x+s,y-s,col,6);

